<style>
    @page { margin: 12mm; } * { box-sizing: border-box; } body { margin: 0; background: #fff; color: #1f2937; font-family: DejaVu Sans, Arial, sans-serif; font-size: 10px; line-height: 1.45; } .document { max-width: 190mm; margin: 0 auto; } .document-header { border-bottom: 3px solid #D4AF37; padding-bottom: 12px; } .document-header-table, .document-table, .document-totals { width: 100%; border-collapse: collapse; } .document-logo { max-width: 38mm; max-height: 22mm; } .document-company { color: #111827; font-size: 19px; font-weight: 800; } .document-muted { color: #6b7280; } .document-title { margin: 16px 0 10px; color: #111827; font-size: 17px; font-weight: 800; letter-spacing: .08em; } .document-number { color: #806817; font-size: 11px; font-weight: 800; } .document-meta { margin: 12px 0 16px; } .document-meta td { width: 50%; padding: 9px 11px; vertical-align: top; border: 1px solid #e5e7eb; } .document-label { color: #6b7280; font-size: 8px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; } .document-value { margin-top: 3px; font-size: 10px; font-weight: 600; } .document-table th { background: #111827; color: #fff; font-size: 9px; font-weight: 700; padding: 8px; text-align: left; } .document-table td { border-bottom: 1px solid #e5e7eb; padding: 8px; vertical-align: top; } .document-table .right, .document-totals .right { text-align: right; } .document-totals { margin: 16px 0 0 auto; width: 72mm; } .document-totals td { padding: 5px 0; } .document-total td { border-top: 2px solid #D4AF37; color: #111827; font-size: 13px; font-weight: 800; padding-top: 9px; } .document-notes { margin-top: 18px; border-left: 3px solid #D4AF37; background: #fafafa; padding: 9px 11px; } .document-footer { margin-top: 26px; border-top: 1px solid #e5e7eb; color: #6b7280; font-size: 8px; padding-top: 9px; text-align: center; } .document-alert { border: 1px solid #D4AF37; color: #111827; font-weight: 700; margin: 8px 0 14px; padding: 7px; text-align: center; } @media print { .no-print { display: none !important; } }
</style>
